#!/usr/bin/env node
// ====== Code Summary ======
// Drift guard for the committed `src/api/generated.ts` (openapi-typescript output — the parity
// baseline `_contractParity.ts` checks every hand-written api/*.ts mirror against, see
// agent-memory/frontend/gen-types-constraint.md). Nothing regenerates that file automatically, so
// a backend response-model change can silently drift it forever — `_contractParity.ts` only catches
// a drift AFTER it has been regenerated by hand; this script catches the "forgot to regenerate at
// all" failure mode by re-running the generator against a live backend and diffing the result.
//
// Requires a reachable backend (OPENAPI_URL) — this is NOT part of `npm run test` (which must stay
// deterministic/offline). Run it explicitly:
//   docker compose -f compose/compose.dev-cpu.yml exec -e OPENAPI_URL=http://docforge_app:8000/openapi.json \
//     docforge_frontend sh -c 'cd /frontend && npm run check:generated-types'
// Outside the dev container, point OPENAPI_URL at whatever backend you have reachable. When the
// backend is unreachable (offline CI, no stack up) this exits 0 with a clear SKIP message instead
// of failing the build — the guard degrades to a no-op, never a false failure.

import { execFileSync } from "node:child_process";
import http from "node:http";
import https from "node:https";

const OPENAPI_URL = process.env.OPENAPI_URL ?? "http://docforge_app:8000/openapi.json";
const PROBE_TIMEOUT_MS = 3000;

/** Quick reachability probe so an offline run degrades to a clean skip, never a hard failure. */
function probe(url) {
  return new Promise((resolve) => {
    const client = url.startsWith("https") ? https : http;
    const req = client.get(url, { timeout: PROBE_TIMEOUT_MS }, (res) => {
      res.resume();
      resolve(res.statusCode != null && res.statusCode < 500);
    });
    req.on("error", () => resolve(false));
    req.on("timeout", () => {
      req.destroy();
      resolve(false);
    });
  });
}

const reachable = await probe(OPENAPI_URL);
if (!reachable) {
  console.log(
    `[check-generated-types] SKIP — ${OPENAPI_URL} unreachable. This guard only runs against a ` +
      "live backend; see agent-memory/frontend/gen-types-constraint.md for how to launch the dev " +
      "stack and point OPENAPI_URL at it.",
  );
  process.exit(0);
}

// openapi-typescript's own `--check` flag regenerates in-memory and diffs against the existing
// output file, exiting non-zero on any difference — exactly the drift check we need, same flags as
// `gen:types` (package.json) so a real regen and this check never disagree on FORMATTING, only content.
try {
  execFileSync(
    "npx",
    ["openapi-typescript", OPENAPI_URL, "-o", "src/api/generated.ts", "--enum", "--alphabetize", "--check"],
    { stdio: "inherit" },
  );
} catch {
  console.error(
    "\n[check-generated-types] DRIFT — src/api/generated.ts is stale against the live backend's " +
      "OpenAPI schema. Run `npm run gen:types` (OPENAPI_URL pointed at the backend) and commit the " +
      "result, then re-check `_contractParity.ts` (npx tsc --noEmit) for any newly-surfaced hand-mirror drift.",
  );
  process.exit(1);
}

console.log("[check-generated-types] OK — src/api/generated.ts matches the live backend's OpenAPI schema.");
